    # Extract the matrix and exponent from inputs
    M = inputs.get('M', [[3, 14], [12, 13]])
    n = inputs.get('n', 29)
    mod = inputs.get('mod', 695754)

    def matrix_mult(A, B, mod):
        """Multiply two 2x2 matrices modulo mod"""
        result = [[0, 0], [0, 0]]
        for i in range(2):
            for j in range(2):
                for k in range(2):
                    result[i][j] = (result[i][j] + A[i][k] * B[k][j]) % mod
        return result

    def matrix_power(M, exp, mod):
        """Compute M^exp modulo mod using fast exponentiation"""
        if exp == 0:
            return [[1, 0], [0, 1]]  # Identity matrix
        if exp == 1:
            return [[M[i][j] % mod for j in range(2)] for i in range(2)]

        # Fast exponentiation
        result = [[1, 0], [0, 1]]  # Identity matrix
        base = [[M[i][j] % mod for j in range(2)] for i in range(2)]

        while exp > 0:
            if exp % 2 == 1:
                result = matrix_mult(result, base, mod)
            base = matrix_mult(base, base, mod)
            exp //= 2

        return result

    result_matrix = matrix_power(M, n, mod)

    # Sum all entries of the result matrix
    total = sum(result_matrix[i][j] for i in range(2) for j in range(2))

    return float(total % mod)

